UPDATE TB_CTRL_CMD_RST

	
		SET PUMP_CMD_STATUS = #{TO_STATUS}
		WHERE CTRL_ID = #{CTRL_ID} AND PUMP_CMD_YN = 'Y' AND PUMP_CMD_STATUS = #{FROM_STATUS}
	
	
		SET LOCAL_CMD_STATUS = #{TO_STATUS}
		WHERE CTRL_ID = #{CTRL_ID} AND LOCAL_CMD_YN = 'Y' AND LOCAL_CMD_STATUS = #{FROM_STATUS}
	
	
		SET NATIONAL_CMD_STATUS = #{TO_STATUS}
		WHERE CTRL_ID = #{CTRL_ID} AND NATIONAL_CMD_YN = 'Y' AND NATIONAL_CMD_STATUS = #{FROM_STATUS}
